 76→/**
 77→ * Check if running in local development mode.
 78→ */
 79→export function isLocalDev(env: { ENVIRONMENT: string }): boolean {
 80→  return env.ENVIRONMENT === "development";
 81→}
 82→
 83→/**
 84→ * Check if a user should be treated as admin.
 85→ * In local development, all users are admins.
 86→ */
 87→export function isAdmin(env: { ENVIRONMENT: string }, dbIsAdmin: boolean | number): boolean {
 88→  return isLocalDev(env) || dbIsAdmin === true || dbIsAdmin === 1;
 89→}
