 72→export async function fetchCheckpoints(
 73→  org: string,
 74→  repo: string,
 75→  branch: string = "main",
 76→  options?: { source?: "github" }
 77→): Promise<CheckpointsResponse> {
 78→  const params = new URLSearchParams({ branch });
 79→  if (options?.source) {
 80→    params.set("source", options.source);
 81→  }
 82→  return request<CheckpointsResponse>(
 83→    `/api/v1/cache/${org}/${repo}/checkpoints?${params.toString()}`
 84→  );
 85→}
