204→// Resolve checkpoint location - finds which branches a checkpoint exists on
205→// Used when the original branch has been deleted (e.g., after PR merge)
206→export interface CheckpointResolveResponse {
207→  checkpoint_id: string;
208→  branches: string[];
209→  default_branch: string | null;
210→  suggested_branch: string;
211→  needs_redirect: boolean;
212→  requested_branch: string | null;
213→  checkpoint: CheckpointInfo | null;
214→  repo_full_name: string;
215→}
