217→export async function resolveCheckpoint(
218→  org: string,
219→  repo: string,
220→  checkpointId: string,
221→  requestedBranch?: string,
222→): Promise<CheckpointResolveResponse> {
223→  const params = requestedBranch
224→    ? `?branch=${encodeURIComponent(requestedBranch)}`
225→    : "";
226→  return request<CheckpointResolveResponse>(
227→    `/api/v1/cache/${org}/${repo}/checkpoints/resolve/${encodeURIComponent(checkpointId)}${params}`
228→  );
229→}
