26→export function useCommitsQuery(org: string, repo: string) {
27→  return useQuery<RepoCommitsResponse>({
28→    queryKey: ["github", "commits", org, repo],
29→    queryFn: () => fetchRepoCommits(org, repo),
30→    staleTime: 5 * 60 * 1000, // 5 minutes
31→  });
32→}
33→
34→export function useCheckpointStatusQuery(org: string, repo: string) {
35→  return useQuery<CheckpointStatusResponse>({
36→    queryKey: ["github", "checkpoint-status", org, repo],
37→    queryFn: () => fetchCheckpointStatus(org, repo),
38→    staleTime: 5 * 60 * 1000, // 5 minutes
39→  });
40→}
41→
42→export function useCheckpointsQuery(org: string, repo: string, branch: string = "main") {
43→  return useQuery<CheckpointsResponse>({
44→    queryKey: ["github", "checkpoints", org, repo, branch],
45→    queryFn: () => fetchCheckpoints(org, repo, branch),
46→    staleTime: 5 * 60 * 1000, // 5 minutes
47→  });
48→}
49→
50→export function useBranchesQuery(org: string, repo: string) {
51→  return useQuery<BranchesResponse>({
52→    queryKey: ["github", "branches", org, repo],
53→    queryFn: () => fetchBranches(org, repo),
54→    staleTime: 10 * 60 * 1000, // 10 minutes
55→  });
56→}
57→
58→export function useCheckpointTranscriptQuery(
59→  org: string,
60→  repo: string,
61→  checkpointId: string,
62→  options?: { enabled?: boolean }
63→) {
64→  return useQuery<CheckpointTranscriptResponse>({
65→    queryKey: ["github", "checkpoint-transcript", org, repo, checkpointId],
66→    queryFn: () => fetchCheckpointTranscript(org, repo, checkpointId),
67→    enabled: options?.enabled ?? true,
68→  });
69→}
70→
71→// Resolve a checkpoint by ID - finds which branches it exists on
72→// Used when the requested branch is deleted (e.g., after PR merge)
73→export function useResolveCheckpointQuery(
74→  org: string,
75→  repo: string,
76→  checkpointId: string,
77→  requestedBranch?: string,
78→  options?: { enabled?: boolean }
79→) {
80→  return useQuery<CheckpointResolveResponse>({
81→    queryKey: ["github", "checkpoint-resolve", org, repo, checkpointId, requestedBranch],
82→    queryFn: () => resolveCheckpoint(org, repo, checkpointId, requestedBranch),
83→    enabled: options?.enabled ?? true,
84→    staleTime: 5 * 60 * 1000, // 5 minutes
85→  });
86→}
