 44→interface CheckpointsPageProps {
 45→  org: string;
 46→  repo: string;
 47→  branch: string;
 48→}
 49→
 50→export function CheckpointsPage(props: CheckpointsPageProps) {
 51→  const { org, repo, branch } = props;
 52→  const navigate = useNavigate();
 53→  const queryClient = useQueryClient();
 54→  const [searchQuery, setSearchQuery] = useState("");
 55→  const { data: statusData, error: statusError } = useCheckpointStatusQuery(org, repo);
 56→  const { data, isLoading, error } = useCheckpointsQuery(org, repo, branch);
 57→  const { data: branchesData } = useBranchesQuery(org, repo);
 58→  const repoOptions = useRepoBreadcrumbOptions(org);
 59→
 60→  const handleBranchChange = (newBranch: string | null) => {
 61→    if (!newBranch) return;
 62→    navigate({
 63→      to: "/gh/$org/$repo/checkpoints/$branch",
 64→      params: { org, repo, branch: newBranch },
 65→    });
 66→  };
 67→
 68→  const branches = branchesData?.branches ?? [];
 69→  const defaultBranch = branchesData?.default_branch ?? "main";
 70→
 71→  // Sort branches with default branch first, then create options for Combobox
 72→  const sortedBranches = [...branches].sort((a, b) => {
 73→    if (a === defaultBranch) return -1;
 74→    if (b === defaultBranch) return 1;
 75→    return a.localeCompare(b);
 76→  });
 77→
 78→  const branchOptions: ComboboxOption[] = sortedBranches.map((b) => ({
 79→    id: b,
 80→    label: b,
 81→  }));
 82→  // Client-side search filtering - searches the displayed title and author
 83→  const allCheckpoints = data?.checkpoints ?? [];
 84→  const checkpoints = searchQuery.trim()
 85→    ? allCheckpoints.filter((cp) => {
 86→        const query = searchQuery.toLowerCase();
 87→        // Search the displayed title (prompt if exists, otherwise commit message)
 88→        const prompt = cp.sessions?.[0]?.prompt?.trim();
 89→        const displayedTitle = (
 90→          prompt && prompt.length > 0 ? prompt : (cp.commitMessage ?? "")
 91→        ).toLowerCase();
 92→        const author = cp.commitAuthorUsername?.toLowerCase() ?? "";
 93→        return displayedTitle.includes(query) || author.includes(query);
 94→      })
 95→    : allCheckpoints;
 96→
 97→  // =============================================================================
 98→  // LOCAL DEV ONLY: Fetch from GitHub button
 99→  // In local development, the D1 database isn't populated with checkpoint data.
100→  // This button fetches directly from GitHub to allow testing the UI.
101→  // import.meta.env.DEV is false in production builds, so this code is tree-shaken.
102→  // =============================================================================
103→  const isDev = import.meta.env.DEV;
104→  const [isFetchingFromGitHub, setIsFetchingFromGitHub] = useState(false);
105→
106→  const handleFetchFromGitHub = async () => {
107→    setIsFetchingFromGitHub(true);
108→    try {
109→      const response = await fetchCheckpoints(org, repo, branch, {
110→        source: "github",
111→      });
112→      queryClient.setQueryData(
113→        ["github", "checkpoints", org, repo, branch],
114→        response,
115→      );
116→    } catch (err) {
117→      console.error("Failed to fetch from GitHub:", err);
118→    } finally {
119→      setIsFetchingFromGitHub(false);
120→    }
121→  };
122→  // =============================================================================
123→
124→  // Use whichever error arrives first (status is faster, catches 404s early)
125→  const anyError = statusError || error;
126→  const isRepoNotFound = anyError?.message.includes("Repository not found");
127→
128→  // Repo-level 404 — render the standard not-found page
129→  if (isRepoNotFound) {
130→    return (
131→      <Page noPadding>
132→        <div className="flex min-h-[calc(100dvh-var(--global-header-height))]">
133→          <NotFoundContent />
134→        </div>
135→      </Page>
136→    );
137→  }
138→
139→  if (isAuthError(anyError)) {
140→    return (
141→      <Page pageTitle={`${org}/${repo}`} breadcrumbs={(statusData || data) ? getCheckpointBreadcrumbs({ org, repo, branch, repoOptions }) : undefined}>
142→        <ReauthenticateState />
143→      </Page>
144→    );
145→  }
146→
147→  const isBranchNotFound = error instanceof ApiError && error.status === 404;
148→  const genericError = isBranchNotFound ? statusError : anyError;
149→  if (genericError && !isBranchNotFound) {
150→    return (
151→      <Page pageTitle={`${org}/${repo}`} breadcrumbs={(statusData || data) ? getCheckpointBreadcrumbs({ org, repo, branch, repoOptions }) : undefined}>
152→        <div className="border border-default rounded bg-raised p-8">
153→          <div className="text-center">
154→            <p className="text-red-500">
155→              Failed to load checkpoints: {genericError.message}
156→            </p>
157→          </div>
158→        </div>
159→      </Page>
160→    );
161→  }
162→
163→  const hasCheckpoints = data && data.checkpoints.length > 0;
164→  const noCheckpoints = data && data.checkpoints.length === 0;
165→  // Use the fast status query to decide UI before checkpoints finish loading
166→  const repoHasCheckpoints = statusData && statusData.checkpoint_count > 0;
167→  // Show toolbar when we know there are checkpoints (or data already loaded with them)
168→  const showToolbar = hasCheckpoints || repoHasCheckpoints || data?.session_branch_exists === true;
169→
170→  // Empty state conditions — use full data when available, fall back to status data (with error guard)
171→  const showNoAccess =
172→    (noCheckpoints && data.app_has_access === false) ||
173→    (!data && !anyError && statusData?.checkpoint_count === 0 && statusData?.app_has_access === false);
174→
175→  // CLI install: app has access but no session branch yet (null means not synced)
176→  const showCliInstall =
177→    (noCheckpoints && data.app_has_access === true && !data.session_branch_exists) ||
178→    (!data && !anyError && statusData?.checkpoint_count === 0 && statusData?.app_has_access === true && !statusData.session_branch_exists);
179→
180→  const showNoBranchCheckpoints =
181→    noCheckpoints && data.app_has_access === true && data.session_branch_exists === true;
182→
183→  return (
184→    <Page pageTitle={`${org}/${repo}`} breadcrumbs={(statusData || data) ? getCheckpointBreadcrumbs({ org, repo, branch, repoOptions }) : undefined}>
185→      {/* Branch selector and search */}
186→      {showToolbar && <div className="pt-4 pb-4 flex items-center gap-2">
187→        <Combobox
188→          options={branchOptions}
189→          size="large"
190→          value={[branch]}
191→          onChange={(selected) => handleBranchChange(selected[0] ?? null)}
192→        >
193→          <ComboboxTrigger className="max-w-52 shrink-0 justify-start">
194→            <span className="flex items-center gap-1.5 w-full">
195→              <BranchIcon size={18} className="shrink-0" />
196→              <span className="truncate">{branch}</span>
197→              <ChevronDownIcon size={18} className="shrink-0 ml-auto" />
198→            </span>
