// Thin Turbopuffer REST client for checkpoint search (BM25 full-text)

export interface TurbopufferSearchResult {
  checkpoint_id: string;
}

interface TurbopufferQueryResponse {
  // Turbopuffer returns row-oriented data
  data: Array<{
    id: number;
    dist: number;
    attributes: {
      checkpoint_id?: string[];
    };
  }>;
}

export async function searchCheckpoints(
  apiKey: string,
  repoId: string,
  query: string,
  filters?: { branch?: string },
  limit: number = 50,
): Promise<TurbopufferSearchResult[]> {
  const namespace = `checkpoints-${repoId}`;
  const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}/query`;

  const body: Record<string, unknown> = {
    top_k: limit,
    rank_by: ["text", "BM25", query],
    include_attributes: ["checkpoint_id"],
  };

  if (filters?.branch) {
    body.filters = {
      branch: [["Eq", filters.branch]],
    };
  }

  const resp = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  });

  if (!resp.ok) {
    const text = await resp.text().catch(() => "");
    throw new Error(`Turbopuffer query failed (${resp.status}): ${text}`);
  }

  const result = (await resp.json()) as TurbopufferQueryResponse;

  // Deduplicate checkpoint IDs (multiple vectors may map to the same checkpoint)
  const seen = new Set<string>();
  const results: TurbopufferSearchResult[] = [];

  for (const row of result.data) {
    const id = row.attributes?.checkpoint_id?.[0];
    if (id && !seen.has(id)) {
      seen.add(id);
      results.push({ checkpoint_id: id });
    }
  }

  return results;
}

