// Search checkpoints using Turbopuffer BM25 full-text search
repoRoutes.get("/:org/:repo/checkpoints/search", optionalAuth, rateLimitUnauthenticated, async (c) => {
  const userId = c.get("userId") as string | undefined;

  const org = c.req.param("org");
  const repo = c.req.param("repo");
  const repoFullName = `${org}/${repo}`;

  const query = c.req.query("q");
  const branch = c.req.query("branch");

  if (!query || query.trim().length === 0) {
    return c.json({ error: "Query parameter 'q' is required" }, 400);
  }

  if (branch && !isValidBranchName(branch)) {
    return c.json({ error: "Invalid branch name format" }, 400);
  }

  try {
    const apiKey = c.env.TURBOPUFFER_API_KEY;
    if (!apiKey) {
      return c.json({ error: "Search is not configured" }, 503);
    }

    const db = getDb(c.env);

    const repoAccess = await checkRepoAccess(
      db,
      repoFullName,
      userId,
      { requireRepo: true },
    );
    if (repoAccess instanceof Response) return repoAccess;

    const repoRecord = repoAccess;

    const searchResults = await searchCheckpoints(
      apiKey,
      repoRecord.id,
      query.trim(),
      branch ? { branch } : undefined,
    );

    if (searchResults.length === 0) {
      return c.json({
        checkpoints: [],
        repo_full_name: repoFullName,
        updated_at: new Date().toISOString(),
        from_cache: false,
        app_has_access: repoRecord.app_has_access ?? null,
        session_branch_exists: repoRecord.checkpoints_backfilled_at ? true : null,
      });
    }

    const checkpointIds = searchResults.map((r) => r.checkpoint_id);
    const dbCheckpoints = await db.checkpoints.getByIds(repoRecord.id, checkpointIds);

    // Preserve Turbopuffer relevance ordering
    const byId = new Map(dbCheckpoints.map((row) => [row.checkpoint_id, row]));
    const ordered = checkpointIds
      .map((id) => byId.get(id))
      .filter((row): row is CheckpointWithCommit => row != null);

    const checkpoints: CheckpointInfo[] = ordered.map(mapCheckpointToInfo);

    return c.json({
      checkpoints,
      repo_full_name: repoFullName,
      updated_at: new Date().toISOString(),
      from_cache: false,
      app_has_access: repoRecord.app_has_access ?? null,
      session_branch_exists: repoRecord.checkpoints_backfilled_at ? true : null,
    });
  } catch (err) {
    if ((err as any)?.status === 404) {
      return c.json({ error: (err as Error).message }, 404);
    }
    if (isGitHubAuthError(err)) {
      return c.json({ error: "GitHub token expired" }, 401);
    }
    console.error(`Failed to search checkpoints for ${repoFullName}:`, err);
    recordSpanError(err);
    return c.json({ error: "Failed to search checkpoints" }, 500);
  }
});

