241→
242→    // Extract first user message + first assistant message
243→    const parts: string[] = [];
244→    let charsUsed = 0;
245→
246→    for (const msg of result.messages) {
247→      if (charsUsed >= MAX_TRANSCRIPT_CHARS) break;
248→
249→      const remaining = MAX_TRANSCRIPT_CHARS - charsUsed;
250→      const text = msg.content.slice(0, remaining);
251→      parts.push(`[${msg.role}]: ${text}`);
252→      charsUsed += text.length;
253→
254→      // Only take the first user + first assistant
