 20→// TTL for sync:lastUpdate KV entries (7 days)
 21→const SYNC_LAST_UPDATE_TTL = 60 * 60 * 24 * 7;
 22→
 23→// Log with consistent prefix
 24→function log(event: string, data: Record<string, unknown>): void {
 25→  console.log(`[repo-sync-queue] ${event}`, JSON.stringify(data));
 26→}
 27→
 28→// KV key for per-installation rate limit state
 29→function rateLimitKey(installationId: number): string {
 30→  return `github:ratelimit:installation:${installationId}:resetAt`;
 31→}
 32→
 33→// Check if a specific installation is currently rate limited
 34→async function isRateLimited(cache: KVNamespace, installationId: number): Promise<boolean> {
 35→  const key = rateLimitKey(installationId);
 36→  const resetAt = await cache.get(key);
 37→  if (!resetAt) return false;
 38→
 39→  const resetTime = parseInt(resetAt, 10);
 40→  if (Date.now() < resetTime) {
 41→    return true;
 42→  }
 43→
 44→  // Rate limit has expired, clean up
 45→  await cache.delete(key);
 46→  return false;
 47→}
 48→
 49→// Set rate limit marker for a specific installation (called when we hit a rate limit)
 50→async function setRateLimitMarker(
 51→  cache: KVNamespace,
 52→  installationId: number,
 53→  resetAt?: number,
 54→): Promise<void> {
 55→  // Default to 15 minutes from now if no reset time provided
 56→  const resetTime = resetAt ?? Date.now() + 15 * 60 * 1000;
 57→  // Store with TTL of 1 hour (self-cleaning)
 58→  await cache.put(rateLimitKey(installationId), String(resetTime), {
 59→    expirationTtl: 60 * 60,
 60→  });
 61→  log("rate_limit_set", { installationId, resetAt: new Date(resetTime).toISOString() });
 62→}
