 64→// Notify users with access to a repo that data has been updated
 65→// This triggers frontend polling to detect the change and refresh
 66→// Note: This function never throws - errors are logged and swallowed
 67→// to avoid affecting the main sync flow (notification is best-effort)
 68→async function notifyUsersOfRepoUpdate(
 69→  db: Db,
 70→  cache: KVNamespace,
 71→  repoId: string
 72→): Promise<number> {
 73→  try {
 74→    // Get all users with access to this repo (reuse existing utility)
 75→    const userIds = await db.repos.getUsersForRepo(repoId);
 76→
 77→    if (userIds.length === 0) {
 78→      return 0;
 79→    }
 80→
 81→    // Update sync:lastUpdate for each user
 82→    const now = String(Date.now());
 83→    await Promise.all(
 84→      userIds.map((userId) =>
 85→        cache.put(`sync:lastUpdate:${userId}`, now, {
 86→          expirationTtl: SYNC_LAST_UPDATE_TTL,
 87→        })
 88→      )
 89→    );
 90→
 91→    return userIds.length;
 92→  } catch (err) {
 93→    log("notify_users_error", {
 94→      repoId,
 95→      error: errorString(err),
 96→    });
 97→    return 0;
 98→  }
 99→}
