347→// Reconciliation options
348→export interface ReconciliationOptions {
349→  force?: boolean; // Skip staleness check and queue all repos
350→  repoFullName?: string; // Target a specific repo by full name (e.g., "owner/repo")
351→  repoIds?: string[]; // Target specific repos by ID
352→}
353→
354→// Reconciliation result
355→export interface ReconciliationResult {
356→  reposQueued: number;
357→  usersQueued: number;
358→  targetedRepo?: string; // The repo that was targeted (if any)
359→}
360→
361→// Daily reconciliation cron handler
362→// Queues stale repos for checkpoint sync and identifies stale users
363→export async function handleReconciliationCron(
364→  env: Env,
365→  options: ReconciliationOptions = {},
366→): Promise<ReconciliationResult> {
367→  const now = new Date();
368→  const staleThreshold = new Date(
369→    now.getTime() - 24 * 60 * 60 * 1000,
370→  ).toISOString();
371→  const isTargeted = !!(options.repoFullName || options.repoIds?.length);
372→
373→  log("cron_started", {
374→    threshold: staleThreshold,
375→    force: options.force ?? false,
376→    targeted: isTargeted,
377→    repoFullName: options.repoFullName,
378→    repoIds: options.repoIds,
379→  });
380→
381→  const db = getDb(env);
382→
383→  // A. Queue repos for checkpoint reconciliation
384→  let reposToQueue: { id: string; full_name: string }[];
385→  try {
386→    reposToQueue = await db.repos.getForReconciliation({
387→      repoFullName: options.repoFullName,
388→      repoIds: options.repoIds,
389→      force: options.force,
390→      staleThreshold,
391→    });
392→  } catch (err) {
393→    if (options.repoFullName) {
394→      log("cron_error_repo_not_found", {
395→        repoFullName: options.repoFullName,
396→        error: errorString(err),
397→      });
398→      return { reposQueued: 0, usersQueued: 0, targetedRepo: options.repoFullName };
399→    }
400→    log("cron_error_fetching_repos", { error: errorString(err) });
401→    return { reposQueued: 0, usersQueued: 0 };
402→  }
403→
404→  const reposQueued = await queueRepoSyncBatch(
405→    env.REPO_SYNC_QUEUE,
406→    reposToQueue,
407→    "reconciliation",
408→    1,
409→  );
410→
411→  // B. Queue stale users for repo sync (skip if targeting specific repos)
412→  let usersQueued = 0;
413→  if (!isTargeted) {
414→    try {
415→      const staleUsers = await db.refreshState.getStaleUsers(staleThreshold, 100);
416→      usersQueued = await queueUserRepoSyncBatch(
417→        env.USER_REPO_SYNC_QUEUE,
418→        staleUsers,
419→        "reconciliation",
420→      );
421→    } catch (err) {
422→      log("cron_error_fetching_users", { error: errorString(err) });
423→    }
424→  }
425→
426→  const result: ReconciliationResult = {
427→    reposQueued,
428→    usersQueued,
429→    targetedRepo: options.repoFullName,
430→  };
431→
432→  log("cron_complete", { ...result });
433→
434→  return result;
435→}
