 995→// Process push to any branch (except CHECKPOINT_BRANCH) - stores commit data
 996→export async function processCommitPushEvent(
 997→  eventType: string,
 998→  payload: Record<string, unknown>,
 999→  db: Db,
1000→  env: Env
1001→): Promise<void> {
1002→  if (eventType !== "push") return;
1003→
1004→  const repo = payload.repository as Record<string, unknown> | undefined;
1005→  if (!repo?.full_name) return;
1006→
1007→  const repoFullName = repo.full_name as string;
1008→  const ref = payload.ref as string | undefined;
1009→  const deleted = payload.deleted as boolean | undefined;
1010→
1011→  // Only process branch pushes (not tags)
1012→  if (!ref?.startsWith("refs/heads/")) return;
1013→  const branch = ref.replace("refs/heads/", "");
1014→
1015→  // Skip CHECKPOINT_BRANCH - handled by processSessionsPushEvent
1016→  if (branch === CHECKPOINT_BRANCH) return;
1017→
1018→  // Skip TRAILS_BRANCH - handled by processTrailsPushEvent
1019→  if (branch === TRAILS_BRANCH) return;
1020→
1021→  // Validate installation exists before processing any DB operations
1022→  // This prevents unauthorized data modification from compromised webhook secrets
1023→  const installationId = await validateInstallation(payload, db, `Commit push ${repoFullName}`);
1024→  if (installationId === null) {
1025→    logCheckpointMetric("skip_no_installation", { repo: repoFullName, branch });
