1027→  }
1028→
1029→  trace.getActiveSpan()?.setAttribute("github.installation_id", installationId);
1030→
1031→  // Find the global repo record
1032→  const repoGithubId = repo.id as number;
1033→  const repoRecord = await db.repos.getByGithubId(repoGithubId);
1034→  if (!repoRecord) {
1035→    logCheckpointMetric("skip_repo_not_found", { repo: repoFullName });
1036→    return;
1037→  }
1038→
1039→  // Handle branch deletion
1040→  if (deleted) {
1041→    const deletedCount = await db.checkpoints.deleteCommitsByBranch(repoRecord.id, branch);
1042→    const orphansDeleted = await db.checkpoints.deleteOrphaned(repoRecord.id);
1043→    if (deletedCount > 0 || orphansDeleted > 0) {
1044→      await db.checkpoints.recalculateCount(repoRecord.id);
1045→    }
1046→    logCheckpointMetric("branch_deleted", { repo: repoFullName, branch, deletedCount, orphansDeleted });
1047→    return;
1048→  }
1049→
1050→  // Handle force push: clear stale checkpoint commits for this branch and queue re-sync.
1051→  // Force pushes rewrite history, so old checkpoint commits may no longer be reachable.
1052→  // The push payload only contains newly pushed commits (not the full branch), so we
1053→  // delete stale entries immediately and queue a full backfill to re-discover the rest.
1054→  const forced = payload.forced as boolean | undefined;
1055→  if (forced) {
1056→    const deletedCount = await db.checkpoints.deleteCommitsByBranch(repoRecord.id, branch);
1057→    const orphansDeleted = await db.checkpoints.deleteOrphaned(repoRecord.id);
1058→    if (deletedCount > 0 || orphansDeleted > 0) {
1059→      await db.checkpoints.recalculateCount(repoRecord.id);
1060→    }
1061→
1062→    // Invalidate backfill state so next sync does a full re-discovery
1063→    await db.checkpoints.updateSyncState(repoRecord.id, { resetBackfill: true });
1064→
1065→    // Queue immediate re-sync to backfill reachable checkpoints
1066→    if (env?.REPO_SYNC_QUEUE) {
1067→      await queueRepoSyncBatch(env.REPO_SYNC_QUEUE, [{ id: repoRecord.id }], "manual", 10);
1068→    }
1069→
1070→    logCheckpointMetric("force_push_cleanup", { repo: repoFullName, branch, deletedCount, orphansDeleted });
1071→  }
1072→
1073→  // Get commits from push payload
1074→  const commits = payload.commits as Array<Record<string, unknown>> | undefined;

1073→  // Get commits from push payload
1074→  const commits = payload.commits as Array<Record<string, unknown>> | undefined;
1075→  if (!commits?.length) return;
1076→
1077→  const defaultBranch = repoRecord.default_branch || repo.default_branch || "main";
1078→
1079→  // Extract checkpoint IDs from Entire-Checkpoint trailers in commit messages.
1080→  // On non-default branches, skip non-distinct commits (distinct=false means the
1081→  // commit already existed in the repository / was pushed before, e.g. via "Update branch" merge).
1082→  const checkpointCommits: Array<{
1083→    sha: string;
1084→    message: string;
1085→    checkpointId: string;
1086→    author: { name: string; username?: string };
1087→    timestamp: string;
1088→  }> = [];
1089→
1090→  let skippedNonDistinct = 0;
1091→
1092→  for (const commit of commits) {
1093→    if (branch !== defaultBranch && commit.distinct === false) {
1094→      skippedNonDistinct++;
1095→      continue;
1096→    }
1097→
1098→    const message = commit.message as string;
1099→    const checkpointIds = extractCheckpointIds(message);
1100→
1101→    for (const checkpointId of checkpointIds) {
1102→      checkpointCommits.push({
1103→        sha: commit.id as string,
1104→        message,
1105→        checkpointId,
1106→        author: {
1107→          name: (commit.author as Record<string, unknown>)?.name as string,
1108→          username: (commit.author as Record<string, unknown>)?.username as string | undefined,
1109→        },
1110→        timestamp: commit.timestamp as string,
1111→      });
1112→    }
1113→  }
1114→
1115→  if (skippedNonDistinct > 0) {
1116→    logCheckpointMetric("skipped_non_distinct_commits", {
1117→      repo: repoFullName,
1118→      branch,
1119→      skipped: skippedNonDistinct,
1120→    });
1121→  }
1122→
1123→  if (checkpointCommits.length === 0) {
